const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // The user's question is about a future date (January 7, 2025).
    // Earth Engine contains archival data and cannot provide data for future dates.
    // The query will correctly result in an empty image collection.

    const pacificPalisades = ee.Geometry.Point([-118.5387, 34.0486]); // Base point
    const startDate = '2025-01-07';
    const endDate = '2025-01-08'; // A one-day period to capture the specific date

    // Define the two points of interest
    // Point 1: 50 km west. At 34°N, 1° longitude is approx. 92 km. 50 km = 50/92 = 0.543°
    const pointWest = ee.Geometry.Point([-118.5387 - 0.543, 34.0486]);

    // Point 2: 50 km southwest. 1° latitude is approx. 111 km. 50 km = 50/111 = 0.45°
    // Component distance for SW is 50/sqrt(2) = 35.35 km
    const latOffset = 35.35 / 111; // degrees
    const lonOffset = 35.35 / 92; // degrees
    const pointSouthwest = ee.Geometry.Point([-118.5387 - lonOffset, 34.0486 - latOffset]);

    // 2. Data Acquisition & Check
    const collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
        .select('tropospheric_NO2_column_number_density')
        .filterDate(startDate, endDate)
        .filterBounds(pacificPalisades.buffer(60000)); // Buffer to ensure points are covered

    const collectionSize = await collection.size().getInfo();

    // 3. Processing, Calculation, & Final Answer
    // The collection size will be 0 because the date is in the future.
    if (collectionSize === 0) {
        console.log(`Query Date: ${startDate}`);
        console.log("Image Collection Size: 0");
        console.log("Reason: The requested date is in the future. Earth Engine does not contain forecast data.");
        console.log("C1: Empty Collection (No images found in date/location for one or both comparison points).");
        console.log("A");
    } else {
        // This block is unlikely to be executed but included for completeness.
        const image = collection.mean(); // Create a composite for the day

        const valueWest = image.reduceRegion({
            reducer: ee.Reducer.mean(),
            geometry: pointWest,
            scale: 1000,
            maxPixels: 1e9
        }).get('tropospheric_NO2_column_number_density');

        const valueSouthwest = image.reduceRegion({
            reducer: ee.Reducer.mean(),
            geometry: pointSouthwest,
            scale: 1000,
            maxPixels: 1e9
        }).get('tropospheric_NO2_column_number_density');

        const valW = await valueWest.getInfo();
        const valSW = await valueSouthwest.getInfo();

        if (valW === null || valSW === null) {
            console.log("West NO2:", valW);
            console.log("Southwest NO2:", valSW);
            console.log("C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).");
            console.log("A");
        } else {
            console.log(`NO2 Conc. 50km West (mol/m^2): ${valW.toExponential(4)}`);
            console.log(`NO2 Conc. 50km Southwest (mol/m^2): ${valSW.toExponential(4)}`);
            if (valW > valSW) {
                console.log("A");
            } else {
                console.log("B");
            }
        }
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error("An error occurred during initialization or analysis.", e);
        console.log("D");
    }
}

initEE();
